package com.powercms.cms.sitepackage.entity;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="page_visual_composition",uniqueConstraints=@UniqueConstraint(columnNames="page_id"))
public class PageVisualCompositionEntity { @Id private UUID id; @Column(name="page_id",nullable=false) private UUID pageId; @Column(name="template_id",nullable=false) private UUID templateId; @Column(name="zones_json",nullable=false,columnDefinition="text") private String zonesJson="{}"; @Column(nullable=false) private int version=1; @Column(name="updated_by",length=100) private String updatedBy; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt; @Column(name="updated_at",nullable=false) private Instant updatedAt; @PrePersist void create(){if(id==null)id=UUID.randomUUID();var n=Instant.now();createdAt=n;updatedAt=n;} @PreUpdate void update(){updatedAt=Instant.now();} public UUID getId(){return id;} public UUID getPageId(){return pageId;} public void setPageId(UUID v){pageId=v;} public UUID getTemplateId(){return templateId;} public void setTemplateId(UUID v){templateId=v;} public String getZonesJson(){return zonesJson;} public void setZonesJson(String v){zonesJson=v;} public int getVersion(){return version;} public void setVersion(int v){version=v;} public String getUpdatedBy(){return updatedBy;} public void setUpdatedBy(String v){updatedBy=v;} public Instant getCreatedAt(){return createdAt;} public Instant getUpdatedAt(){return updatedAt;} }